"use client";
import React from "react";
import { C } from "@/lib/golf";
import { APP_VERSION } from "@/lib/app-version";
import { btn } from "@/components/ui";
import { useUpdatesBlocked } from "@/components/update-safety";
import { updatesBlocked } from "@/lib/update-safety";
// Manual "check for updates" — compares the app build bundled in this page
// with /app-version.json generated by the current deployment. This catches new
// app versions even when the browser does not report a waiting service worker.
export function UpdateChecker() {
  const updateBlocked = useUpdatesBlocked();
  const [status, setStatus] = React.useState<string>("");
  const [latest, setLatest] = React.useState<string | null>(null);
  const [latestBuild, setLatestBuild] = React.useState<string | null>(null);

  // apply = false → passive check: DETECT ONLY. Never activate a waiting worker
  // and never reload. This is what runs on mount and on "Check for updates", so
  // opening this screen can't silently update the app out from under the user.
  // apply = true → the user tapped "Update to X": now we activate/reload.
  const check = async (apply = false) => {
    if (updatesBlocked()) { setStatus("Updates are paused until your round is finished and scores are saved."); return; }
    setStatus("Checking…");
    try {
      let waiting: ServiceWorker | null = null;
      if ("serviceWorker" in navigator) {
        const reg = await navigator.serviceWorker.getRegistration();
        if (reg) {
          await reg.update().catch(() => {});
          await new Promise((r) => setTimeout(r, 1200));
          waiting = reg.waiting;
          // Only chase an installing worker to activation when APPLYING. On a
          // passive check we just note that a download is in flight.
          if (!waiting && reg.installing) {
            if (apply) {
              setStatus("Downloading the new version… it'll apply in a moment.");
              reg.installing.addEventListener("statechange", () => {
                if (reg.waiting && !updatesBlocked()) reg.waiting.postMessage("SKIP_WAITING");
              });
              return;
            }
            setStatus("A new version is downloading — tap Update when it's ready.");
          }
        }
      }

      const res = await fetch(`/app-version.json?ts=${Date.now()}`, {
        cache: "no-store",
        headers: { "Cache-Control": "no-cache" },
      });
      const server = res.ok ? await res.json() : null;
      const serverVersion = typeof server?.version === "string" ? server.version : null;
      const serverBuild = typeof server?.buildId === "string" ? server.buildId : null;
      setLatest(serverVersion);
      setLatestBuild(serverBuild);

      const isNewer = !!serverVersion && serverVersion !== APP_VERSION;

      if (!apply) {
        // Report only — surface the "Update to X" button via hasNewer; don't touch the worker.
        setStatus(
          isNewer
            ? `New version available${serverVersion ? `: ${serverVersion}` : ""}. Tap Update to install.`
            : serverVersion
              ? "You're on the latest version."
              : "Couldn't confirm the current version — try again in a moment.",
        );
        return;
      }

      // Apply path — user explicitly tapped Update.
      if (updatesBlocked()) { setStatus("Updates are paused until your round is finished and scores are saved."); return; }
      if (waiting) {
        setStatus("Updating…");
        waiting.postMessage("SKIP_WAITING"); // controllerchange (register-sw) reloads
      } else if (serverVersion && serverVersion !== APP_VERSION) {
        setStatus(`Updating to ${serverVersion}…`);
        window.location.reload();
      } else if (serverVersion) {
        setStatus("You're on the latest version.");
      } else {
        setStatus("Couldn't confirm the current version — try again in a moment.");
      }
    } catch {
      setStatus("Couldn't check right now — try again in a moment.");
    }
  };

  // Passive detection on mount — safe now that check(false) never activates.
  React.useEffect(() => { check(false); }, []);

  const hasNewer = !updateBlocked && latest && latest !== APP_VERSION;
  return (
    <div style={{ background: C.greenLight, borderRadius: 14, padding: 16, marginTop: 12 }}>
      <div style={{ color: C.cream, fontFamily: "Georgia, serif", fontSize: 18, fontWeight: 700 }}>App version &amp; updates</div>
      <div style={{ color: C.sage, fontSize: 13, marginTop: 8, lineHeight: 1.55 }}>
        Installed as an app? This compares your installed release with the latest deployed release. Updates apply only after you tap Update.
      </div>
      <div style={{ color: C.cream, fontSize: 13, marginTop: 10, lineHeight: 1.7 }}>
        <div><b>Current version:</b> {APP_VERSION}</div>
        <div><b>Latest version:</b> {latest || "Not checked yet"}</div>
        <div style={{ color: C.sage, fontSize: 11, marginTop: 12, lineHeight: 1.6 }}>
          Birdie Num Num — created by Amit Sud
          <br />© 2026 Amit Sud. All rights reserved.
        </div>
      </div>
      {updateBlocked ? <div style={{ color: C.sage, fontSize: 13, marginTop: 12 }}>Updates are paused until your round is finished and scores are saved.</div> : hasNewer ? (
        <button style={{ ...btn(true), marginTop: 12, fontSize: 13 }} onClick={() => check(true)}>Update to {latest}</button>
      ) : (
        <button style={{ ...btn(true), marginTop: 12, fontSize: 13 }} onClick={() => check(false)}>Check for updates</button>
      )}
      {status ? <div style={{ color: hasNewer ? C.gold : C.cream, fontSize: 12, marginTop: 10 }}>{status}</div> : null}
    </div>
  );
}
